//! HID usage (keyboard page 0x07) to per-key LED slot tables.

/// Bragi keyboards index their LED buffer by HID usage: usages 0x04..=0x65
/// map to themselves and the modifiers 0xE0..=0xE7 follow at 105..=112.
pub(crate) fn bragi_led(usage: u16) -> Option<usize> {
    match usage {
        0x04..=0x65 => Some(usage as usize),
        0xe0..=0xe7 => Some(105 + (usage - 0xe0) as usize),
        _ => None,
    }
}

/// Legacy NXP keyboards number their LEDs column-major (12 slots per column);
/// the table is (HID usage, slot) for the 104-key layout.
#[rustfmt::skip]
