#[cfg(test)]
pub(crate) fn nxp_led(usage: u16) -> Option<usize> {
    let usage = u8::try_from(usage).ok()?;
    NXP_KEYS
        .iter()
        .find(|(u, _)| *u == usage)
        .map(|(_, slot)| *slot as usize)
}

#[cfg(test)]
mod tests {
    use super::*;
    use gearwise_core::keys;

    #[test]
    fn bragi_slots_follow_usage() {
        assert_eq!(bragi_led(0x04), Some(4)); // A
        assert_eq!(bragi_led(0x29), Some(41)); // Esc
        assert_eq!(bragi_led(0x3a), Some(58)); // F1
        assert_eq!(bragi_led(0xe0), Some(105)); // Left Ctrl
        assert_eq!(bragi_led(0xe1), Some(106)); // Left Shift
        assert_eq!(bragi_led(0xe7), Some(112)); // Right Super
        assert_eq!(bragi_led(0x70), None);
    }

    #[test]
    fn nxp_table_covers_the_104_key_layout_without_collisions() {
        let mut usages: Vec<u16> = keys::ansi_full().keys.iter().map(|k| k.id).collect();
        usages.sort_unstable();
        let mut table: Vec<u16> = NXP_KEYS.iter().map(|(u, _)| *u as u16).collect();
        table.sort_unstable();
        assert_eq!(usages, table);
        let mut slots: Vec<u8> = NXP_KEYS.iter().map(|(_, s)| *s).collect();
        slots.sort_unstable();
        slots.dedup();
        assert_eq!(slots.len(), 104);
        assert_eq!(nxp_led(0x29), Some(0x00)); // Esc
        assert_eq!(nxp_led(0x04), Some(0x0f)); // A
        assert_eq!(nxp_led(0x2c), Some(0x35)); // Space
    }
}
